        "title": "A Practical Review of Mechanistic Interpretability for Transformer-Based Language Models",
        "author": "arxiv.org",
        "siteName": "arXiv.org",
        "category": "article",
        "language": "Engels",
        "readingTime": "1 min",
        "readingMinutes": 1,
        "wordCount": 184,
        "publishedDate": "2024-07-02",
